async function main(): Promise<void> {
  const arr: any[] = [{ n: 1 }, { n: 2 }];
  arr.forEach((x: any) => { x.n = 5; });
  console.log(JSON.stringify(arr));
  arr.map((x: any) => { x.n++; return x; });
  console.log(JSON.stringify(arr));
  for (const x of arr) x.n = 9;
  console.log(JSON.stringify(arr));
}
